
var gameController;
var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"EnchantedCleopatraAM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
		
		var tmpMess=k.data.split("#");
			console.log(gameController);
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.nwp.fpm!=undefined){
			
			if(gameController.cff!=parseInt(tmpMess[1])){
				
			gameController.cff=parseInt(tmpMess[1]);	
			gameController.awy=parseInt(tmpMess[1]);	
			gameController.sbg=parseInt(tmpMess[1]);	
				
			gameController.nwp.fpm("gbd", "#setText", [gameController.dyp(tmpMess[1]),true])
				
			}
			
			
			
			
			
			}	
			
		}
		
